def resolve_ticker_alias(ticker):
    """Resolve ticker alias to actual ticker symbol"""
    aliases = get_ticker_aliases()
    upper_ticker = ticker.upper()
    
    # Special conversion for Berkshire Hathaway tickers for Yahoo Finance compatibility
    if upper_ticker == 'BRK.B':
        upper_ticker = 'BRK-B'
    elif upper_ticker == 'BRK.A':
        upper_ticker = 'BRK-A'
    
    return aliases.get(upper_ticker, upper_ticker)

def _get_addition_dates_from_start_vectorized(start_date, end_date, frequency, market_days):
    """Vectorized: addition dates from start_date using searchsorted (O(periods * log(n)) instead of O(periods * n)). Returns set of dates."""
    if not market_days:
        return set()
    market_days_sorted = sorted(market_days)
    market_days_ns = np.array([pd.Timestamp(m).value for m in market_days_sorted], dtype=np.int64)
    end_ns = pd.Timestamp(end_date).value
    dates = []
    if frequency == "Weekly":
        current = start_date + pd.Timedelta(weeks=1)
        while current <= end_date:
            idx = np.searchsorted(market_days_ns, current.value, side="left")
            if idx < len(market_days_ns) and market_days_ns[idx] <= end_ns:
                dates.append(market_days_sorted[idx])
            current += pd.Timedelta(weeks=1)
    elif frequency == "Biweekly":
        current = start_date + pd.Timedelta(weeks=2)
        while current <= end_date:
            idx = np.searchsorted(market_days_ns, current.value, side="left")
            if idx < len(market_days_ns) and market_days_ns[idx] <= end_ns:
                dates.append(market_days_sorted[idx])
            current += pd.Timedelta(weeks=2)
    elif frequency == "Monthly":
        current = start_date + pd.DateOffset(months=1)
        while current <= end_date:
            idx = np.searchsorted(market_days_ns, current.value, side="left")
            if idx < len(market_days_ns) and market_days_ns[idx] <= end_ns:
                dates.append(market_days_sorted[idx])
            current += pd.DateOffset(months=1)
    elif frequency == "Quarterly":
        current = start_date + pd.DateOffset(months=3)
        while current <= end_date:
            idx = np.searchsorted(market_days_ns, current.value, side="left")
            if idx < len(market_days_ns) and market_days_ns[idx] <= end_ns:
                dates.append(market_days_sorted[idx])
            current += pd.DateOffset(months=3)
    elif frequency == "Semiannually":
        current = start_date + pd.DateOffset(months=6)
        while current <= end_date:
            idx = np.searchsorted(market_days_ns, current.value, side="left")
            if idx < len(market_days_ns) and market_days_ns[idx] <= end_ns:
                dates.append(market_days_sorted[idx])
            current += pd.DateOffset(months=6)
    elif frequency == "Annually" or frequency == "year":
        current = start_date + pd.DateOffset(years=1)
        while current <= end_date:
            idx = np.searchsorted(market_days_ns, current.value, side="left")
            if idx < len(market_days_ns) and market_days_ns[idx] <= end_ns:
                dates.append(market_days_sorted[idx])
            current += pd.DateOffset(years=1)
    return set(dates)

def parse_raw_sp500_csv():
    """Parse the raw S&P 500 CSV data into a structured DataFrame"""
    try:
        import pandas as pd
        
        st.write("🔍 DEBUG: Starting to parse raw S&P 500 CSV")
        
        # Read the raw CSV file
        df = pd.read_csv('TOP 20 S&P 500 compagnies over time.csv', header=None)
        
        st.write(f"🔍 DEBUG: Raw CSV has {len(df)} rows")
        st.write(f"🔍 DEBUG: First 10 rows: {df.head(10).values.tolist()}")
        
        # The data is structured as: value, company, value, company, etc.
        # We need to parse it into Year, Rank, Company, Ticker, Market_Cap_Billions format
        
        parsed_data = []
        current_year = 1989  # Starting year
        rank = 1
        
        i = 0
        while i < len(df):
            row = df.iloc[i, 0]
            
            # Check if this is a year (numeric value)
            if pd.isna(row) or row == '':
                i += 1
                continue
                
            try:
                # Try to convert to float to see if it's a market cap value
                market_cap = float(row)
                
                # If we have a market cap, the next row should be the company name
                if i + 1 < len(df):
                    company = str(df.iloc[i + 1, 0])
                    
                    # Skip if company name is empty or NaN
                    if company and company != '' and company != 'nan':
                        # Extract ticker from company name
                        ticker = extract_ticker_from_company(company)
                        
                        parsed_data.append({
                            'Year': current_year,
                            'Rank': rank,
                            'Company': company,
                            'Ticker': ticker,
                            'Market_Cap_Billions': market_cap
                        })
                        
                        # Debug output for first few entries
                        if len(parsed_data) <= 25:  # First year + some of second year
                            st.write(f"🔍 DEBUG: Parsed {company} -> {ticker} (Rank {rank}, Year {current_year})")
                        
                        rank += 1
                        if rank > 20:  # Reset for next year
                            st.write(f"🔍 DEBUG: Completed year {current_year}, moving to {current_year + 1}")
                            rank = 1
                            current_year += 1
                
                i += 2  # Skip both market cap and company name
                
            except (ValueError, TypeError):
                # If conversion fails, it might be a year or other data
                i += 1
                continue
        
        if parsed_data:
            return pd.DataFrame(parsed_data)
        else:
            return None
            
    except Exception as e:
        print(f"Error parsing S&P 500 CSV: {e}")
        return None

